// Clasifica el intento y construye la consulta SQL parametrizada.
// Misma semantica que graphrag/service.py del repo principal, sin LLM.

function norm(s) {
  return (s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();
}

const raw = $input.first().json;
const pregunta = String(raw.pregunta ?? raw.body?.pregunta ?? "").trim();
const t = norm(pregunta);
const t0 = norm(pregunta.replace(/^[?¿!¡.\s]+/, ""));

function esc(s) { return String(s).replace(/'/g, "''"); }

const PREFIJOS_PRODUCTO = [
  "en que url puedo comprar el producto",
  "cual es la marca del producto",
  "de que marca es el producto",
  "cual es el precio de",
  "cuanto cuesta",
  "cuanto vale",
  "a como esta el",
  "precio de"
];
const ARTICULOS = ["el ", "la ", "los ", "las ", "del ", "de la ", "de el "];

function limpiar(s) { return s.trim().replace(/[?¿!¡.,;:]$/, "").trim(); }

function extraerNombre() {
  let texto = pregunta.trim().replace(/^[?¿!¡\s]+/, "");
  for (const pref of PREFIJOS_PRODUCTO) {
    if (t0.startsWith(pref)) { texto = texto.substring(pref.length); break; }
  }
  texto = limpiar(texto);
  for (const a of ARTICULOS) {
    if (norm(texto).startsWith(a)) { texto = texto.substring(a.length); break; }
  }
  return limpiar(texto);
}

function extraerCategoria() {
  if (/maletas|loncheras/.test(t)) return "Maletería";
  const m = pregunta.match(/(?:de la |en la |la )?categor[ií]a\s+(?:de\s+)?(.+?)(?:que\b|,|\.|$)/i);
  if (!m) return "";
  let c = limpiar(m[1]);
  c = c.replace(/\s+y\s+cu[aá]nto\s+(?:cuesta|vale).*$/i, "").trim();
  return c;
}

function extraerProveedor() {
  if (/panamericana/.test(t)) return "panamericana";
  if (/exito/.test(t)) return "exito";
  if (/mercadolibre|mercado libre/.test(t)) return "mercadolibre";
  return "";
}

const CAT = "productos_catalogo";
let tipo = "categoria";
let sql = "";

if (/\b(?:m[aá]s barato|menor precio|m[aá]s econ[oó]mico|precio m[ií]nimo|m[ií]nimo)\b/.test(t)) {
  tipo = "min_precio";
  const cat = esc(extraerCategoria());
  sql = `SELECT nombre, precio, marca, proveedor, url_producto FROM ${CAT} ` +
        `WHERE categoria = '${cat}' AND precio IS NOT NULL AND disponible = true ` +
        "ORDER BY precio ASC LIMIT 5";
} else if (/\bmenciona\b/.test(t)) {
  tipo = "categoria";
  const cat = esc(extraerCategoria());
  sql = `SELECT nombre, precio, marca, proveedor, url_producto FROM ${CAT} ` +
        `WHERE categoria = '${cat}' AND disponible = true ORDER BY nombre LIMIT 8`;
} else if (/\b(?:hay .* disponible|hay disponibles|est[aá]n disponible|disponible|disponibles)\b/.test(t)) {
  tipo = "disponibilidad";
  const cat = esc(extraerCategoria());
  const prov = extraerProveedor();
  const provSql = prov ? ` AND proveedor = '${prov}'` : "";
  sql = `SELECT proveedor, count(*) AS total, count(*) FILTER (WHERE disponible) AS disponibles ` +
        `FROM ${CAT} WHERE categoria = '${cat}'${provSql} GROUP BY proveedor`;
} else if (/\b(?:url|comprar|d[oó]nde puedo comprar|referencia de compra)\b/.test(t)) {
  tipo = "referencia_compra";
  const nom = esc(extraerNombre());
  sql = `SELECT nombre, url_producto, sku, proveedor FROM ${CAT} ` +
        `WHERE nombre ILIKE '%${nom}%' AND url_producto IS NOT NULL LIMIT 1`;
} else if (/\b(?:marca del producto|marca de|qu[eé] marca|de qu[eé] marca|marca)\b/.test(t)) {
  tipo = "marca";
  const nom = esc(extraerNombre());
  sql = `SELECT marca, nombre FROM ${CAT} WHERE nombre ILIKE '%${nom}%' LIMIT 1`;
} else if (/\b(?:cu[aá]nto cuesta|cu[aá]nto vale|precio de|cu[aá]l es el precio)\b/.test(t)) {
  tipo = "precio_producto";
  const nom = esc(extraerNombre());
  sql = `SELECT nombre, precio, marca, proveedor, url_producto, disponible FROM ${CAT} ` +
        `WHERE disponible = true AND precio IS NOT NULL AND nombre ILIKE '%${nom}%' ` +
        "ORDER BY precio LIMIT 5";
} else {
  tipo = "categoria";
  const cat = esc(extraerCategoria());
  sql = `SELECT nombre, precio, marca, proveedor, url_producto FROM ${CAT} ` +
        `WHERE categoria = '${cat}' AND disponible = true ORDER BY nombre LIMIT 8`;
}

return [{
  json: { pregunta, tipo, sql }
}];

// Formatea la respuesta legible y marca el hit con la misma logica de
// puntaje de los demas benchmarks del reporte.

const meta = $('Clasificar y SQL').first().json;
const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => !(r && r.success === true && Object.keys(r).length === 1));
const { tipo, pregunta } = meta;

function precio(n) {
  return '$' + Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}

let resumen = '';
let hit = false;

if (tipo === 'precio_producto') {
  if (rows.length) {
    const r = rows[0];
    resumen = `El precio de ${r.nombre} es ${precio(r.precio)} (${r.proveedor || 'proveedor no indicado'}).`;
    hit = true;
  } else {
    resumen = 'No se encontró un producto con precio conocido.';
  }
} else if (tipo === 'min_precio') {
  if (rows.length) {
    const r = rows[0];
    resumen = `El más barato de ${meta.categoria || 'la categoría'} es ${r.nombre} por ${precio(r.precio)} (${r.proveedor || ''}).`;
    hit = true;
  } else {
    resumen = 'No hay productos con precio publicado en esa categoría.';
  }
} else if (tipo === 'categoria') {
  if (rows.length) {
    resumen = `${rows.length} producto(s) disponible(s) en ${meta.categoria || 'la categoría'}: ${rows.map((r) => r.nombre).join(', ')}.`;
    hit = rows.length >= 3;
  } else {
    resumen = 'No hay productos disponibles en esa categoría.';
  }
} else if (tipo === 'disponibilidad') {
  const disponibles = rows.reduce((acc, r) => acc + Number(r.disponibles || 0), 0);
  if (disponibles > 0) {
    resumen = 'Sí, hay productos disponibles.';
    hit = true;
  } else {
    resumen = 'No hay productos disponibles.';
  }
} else if (tipo === 'marca') {
  if (rows.length) {
    resumen = `La marca de ${rows[0].nombre} es ${rows[0].marca}.`;
    hit = true;
  } else {
    resumen = 'No se encontró la marca.';
  }
} else if (tipo === 'referencia_compra') {
  if (rows.length) {
    resumen = `Puedes comprar «${rows[0].nombre}» en: ${rows[0].url_producto}.`;
    hit = true;
  } else {
    resumen = 'No se encontró una URL de compra.';
  }
}

return [{
  json: { pregunta, tipo, resumen, hit, data: rows }
}];
